using System.Globalization;
using System.Security.Cryptography;
using System.Text.Json;
using System.Text.Json.Nodes;
using CsCheck;
using Karry.SharedKernel.Canonical;

namespace Karry.SharedKernel.UnitTests;

/// <summary>
/// RFC 8785 canonicalization (US-P1-AUD-01 AC4) against vectors produced by a real ECMAScript engine
/// (<c>tests/vectors/rfc8785.json</c>, regenerated by <c>generate-jcs-vectors.mjs</c>), plus the properties the ledger
/// relies on.
/// </summary>
[Trait("Story", "US-P1-AUD-01")]
public sealed class JsonCanonicalizerTests
{
    private static readonly JsonElement Vectors = JsonDocument.Parse(File.ReadAllText(VectorFile())).RootElement;

    [Fact]
    public void The_rfc_8785_examples_canonicalize_exactly()
    {
        foreach (var example in Vectors.GetProperty("examples").EnumerateArray())
        {
            JsonCanonicalizer.CanonicalText(example.GetProperty("input").GetString()!, strictNumbers: false)
                .Should().Be(example.GetProperty("expected").GetString());
        }
    }

    [Fact]
    public void Numbers_serialize_like_ecmascript_for_every_appendix_b_bit_pattern()
    {
        foreach (var vector in Vectors.GetProperty("numbers").EnumerateArray())
        {
            var bits = ulong.Parse(vector.GetProperty("bits").GetString()!, NumberStyles.HexNumber, CultureInfo.InvariantCulture);
            var value = BitConverter.UInt64BitsToDouble(bits);
            var raw = value.ToString("R", CultureInfo.InvariantCulture);

            JsonCanonicalizer.SerializeNumber(raw, strict: false).Should().Be(vector.GetProperty("expected").GetString(), $"bits {bits:x16}");
        }
    }

    [Fact]
    public void Three_hundred_random_documents_match_the_ecmascript_reference_byte_for_byte()
    {
        var documents = Vectors.GetProperty("documents").EnumerateArray().ToList();
        documents.Should().HaveCount(300);
        foreach (var document in documents)
        {
            // Strict mode: numbers written by JSON.stringify are exact doubles and must be accepted.
            JsonCanonicalizer.CanonicalText(document.GetProperty("input").GetString()!)
                .Should().Be(document.GetProperty("expected").GetString(), document.GetProperty("input").GetString());
        }
    }

    [Fact]
    public void Key_order_and_whitespace_never_change_the_canonical_form()
    {
        Gen.Dictionary(Gen.String[Gen.Char.AlphaNumeric, 1, 8], Gen.Int[-1_000_000, 1_000_000])[1, 12].Sample(members =>
        {
            var forward = new JsonObject(members.Select(m => KeyValuePair.Create(m.Key, (JsonNode?)JsonValue.Create(m.Value))));
            var backward = new JsonObject(members.Reverse().Select(m => KeyValuePair.Create(m.Key, (JsonNode?)JsonValue.Create(m.Value))));

            var a = JsonCanonicalizer.Canonicalize(forward.ToJsonString());
            var b = JsonCanonicalizer.Canonicalize(backward.ToJsonString(new JsonSerializerOptions { WriteIndented = true }));
            a.Should().Equal(b);
        });
    }

    [Fact]
    public void Canonicalizing_a_canonical_document_changes_nothing()
    {
        foreach (var document in Vectors.GetProperty("documents").EnumerateArray())
        {
            var canonical = document.GetProperty("expected").GetString()!;
            JsonCanonicalizer.CanonicalText(canonical).Should().Be(canonical);
        }
    }

    [Fact]
    public void Any_one_character_change_of_a_value_changes_the_hash()
    {
        Gen.String[Gen.Char.AlphaNumeric, 1, 30].Select(Gen.Int[0, 29]).Sample((text, position) =>
        {
            var index = position % text.Length;
            var changed = text[..index] + (char)(text[index] ^ 1) + text[(index + 1)..];
            var original = Hash($$"""{"meterEnd":{{JsonSerializer.Serialize(text)}}}""");
            var tampered = Hash($$"""{"meterEnd":{{JsonSerializer.Serialize(changed)}}}""");
            tampered.Should().NotEqual(original);
        });
    }

    [Theory]
    [InlineData("""{"a":1,"a":2}""", "Duplicate member")]
    [InlineData("""{"a":"\ud800"}""", "Lone surrogate")]
    [InlineData("""{"amount":0.10000000000000000555}""", "not exactly representable")]
    [InlineData("""{"id":9007199254740993}""", "not exactly representable")]
    [InlineData("""{"broken":""", "Not valid JSON")]
    public void Values_that_would_hash_ambiguously_are_refused(string json, string reason) =>
        ((Action)(() => JsonCanonicalizer.Canonicalize(json))).Should().Throw<FormatException>().WithMessage($"*{reason}*");

    [Fact]
    public void Plain_rfc_mode_accepts_what_strict_mode_refuses() =>
        JsonCanonicalizer.CanonicalText("""{"id":9007199254740993}""", strictNumbers: false).Should().Be("""{"id":9007199254740992}""");

    [Fact]
    public void Exact_decimals_survive_unchanged_in_strict_mode() =>
        JsonCanonicalizer.CanonicalText("""{"b":12.5,"a":-0.002,"c":1000000}""").Should().Be("""{"a":-0.002,"b":12.5,"c":1000000}""");

    private static byte[] Hash(string json) => SHA256.HashData(JsonCanonicalizer.Canonicalize(json));

    private static string VectorFile()
    {
        for (var directory = new DirectoryInfo(AppContext.BaseDirectory); directory is not null; directory = directory.Parent)
        {
            var candidate = Path.Combine(directory.FullName, "tests", "vectors", "rfc8785.json");
            if (File.Exists(candidate))
            {
                return candidate;
            }
        }

        throw new FileNotFoundException("tests/vectors/rfc8785.json not found.");
    }
}
